import { 
  MeshBasicNodeMaterial, 
  PlaneGeometry, 
  Mesh, 
  Group, 
  DirectionalLight, 
  AmbientLight 
} from 'three/webgpu';
import { 
  uv, 
  texture, 
  positionLocal, 
  normalLocal, 
  vec3, 
  mix, 
  uniform 
} from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  // --- Palettes & Spec ---
  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // --- Background Backdrop Plane (to prevent FLAT_VOID) ---
  const bGeo = new PlaneGeometry(7, 6);
  const bMat = new MeshBasicNodeMaterial();
  // Vertical gradient from ink to surface
  bMat.colorNode = mix(
    vec3(0.043, 0.043, 0.063), // ~#0b0b10 / surface
    vec3(0.086, 0.086, 0.114), // ~#16161d / ink
    uv().y
  );
  const backdrop = new Mesh(bGeo, bMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // --- Local Lighting ---
  const keyLight = new DirectionalLight(colors.paper, 1.2);
  keyLight.position.set(3, 4, 5);
  group.add(keyLight);

  const rimLight = new DirectionalLight(colors.accent, 0.8);
  rimLight.position.set(-3, -2, 2);
  group.add(rimLight);

  // --- Core Stat Tile Mesh ---
  const tileGeometry = new PlaneGeometry(3.5, 2.2, 128, 128);
  const tileMaterial = new MeshBasicNodeMaterial();

  // Create displacement uniform control
  const displacementScale = uniform(0.18);

  // Set up material nodes
  tileMaterial.colorNode = texture(null); // Will be assigned on load
  tileMaterial.positionNode = positionLocal.add(
    normalLocal.mul(texture(null, uv()).r.mul(displacementScale))
  );

  const tileMesh = new Mesh(tileGeometry, tileMaterial);
  group.add(tileMesh);

  // --- Load Assets ---
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tileMaterial.colorNode = texture(tex, uv());
      tileMaterial.needsUpdate = true;
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
      // Re-assign position node mapping with the loaded depth texture
      tileMaterial.positionNode = positionLocal.add(
        normalLocal.mul(texture(depthTex, uv()).r.mul(displacementScale))
      );
      tileMaterial.needsUpdate = true;
    });
  }

  // --- Text Overlay Rendering (Stat Value + Label) ---
  const trackerValue = ctx.fontAtlas.createText('0.0024', {
    fontSize: 0.38,
    color: colors.paper,
    align: 'center'
  });
  trackerValue.position.set(0, 0.2, 0.15);
  group.add(trackerValue);

  const labelText = ctx.fontAtlas.createText('CALIBRE ACCURACY', {
    fontSize: 0.11,
    color: colors.accent,
    align: 'center',
    letterSpacingPx: 3
  });
  labelText.position.set(0, -0.35, 0.15);
  group.add(labelText);

  // --- Interactions & Motion ---
  let hoverTimeline = null;
  let clickTimeline = null;

  const onPointerOver = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    // Hover lift (rise-in)
    hoverTimeline.to(tileMesh.position, {
      z: 0.15,
      y: 0.05,
      duration: 0.4,
      ease: 'power3.out'
    });
    hoverTimeline.to(displacementScale, {
      value: 0.28,
      duration: 0.4,
      ease: 'power3.out'
    }, 0);
  };

  const onPointerOut = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(tileMesh.position, {
      z: 0,
      y: 0,
      duration: 0.5,
      ease: 'power2.out'
    });
    hoverTimeline.to(displacementScale, {
      value: 0.18,
      duration: 0.5,
      ease: 'power2.out'
    }, 0);
  };

  const onPointerDown = () => {
    if (clickTimeline) clickTimeline.kill();
    clickTimeline = gsap.timeline();
    // Press down
    clickTimeline.to(tileMesh.scale, {
      x: 0.96,
      y: 0.96,
      z: 0.96,
      duration: 0.12,
      ease: 'back.out(2)'
    });

    // Emit navigation event
    ctx.emit('hub-features.select', { id: config.id });
  };

  const onPointerUp = () => {
    if (clickTimeline) clickTimeline.kill();
    clickTimeline = gsap.timeline();
    clickTimeline.to(tileMesh.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.35,
      ease: 'power3.out'
    });
  };

  // Bind handlers
  group.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    pointerdown: onPointerDown,
    pointerup: onPointerUp
  };

  // --- Cinematic Primitives ---
  const activePrimitives = [];
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives[prim.name]) {
        const pInstance = ctx.primitives[prim.name](group, prim.params);
        if (pInstance) activePrimitives.push(pInstance);
      }
    }
  }

  // Defensively inject parallax-scroll if not listed, as per Render Mode Guidance
  const hasParallax = config.cinematicPrimitives?.some(p => p.name === 'parallax-scroll');
  if (!hasParallax && ctx.primitives['parallax-scroll']) {
    const pInstance = ctx.primitives['parallax-scroll'](tileMesh, { intensity: 0.25 });
    if (pInstance) activePrimitives.push(pInstance);
  }

  // --- Clean Up ---
  group.userData.cleanup = () => {
    tileGeometry.dispose();
    tileMaterial.dispose();
    bGeo.dispose();
    bMat.dispose();
    if (hoverTimeline) hoverTimeline.kill();
    if (clickTimeline) clickTimeline.kill();
    activePrimitives.forEach(p => {
      if (typeof p.cleanup === 'function') p.cleanup();
    });
  };

  return group;
}
